func maxFloat64(xs []float64) float64 {
        if len(xs) == 0 {
                return 0
        }
        m := xs[0]
        for _, x := range xs[1:] {
                if x > m {
                        m = x
                }
        }
        return m
}

func classifyConvergence(steps []float64) string {
        if len(steps) <= 1 {
                return "converging"
        }
        nonIncreasing := true
        nonDecreasing := true
        hasIncrease := false
        for i := 1; i < len(steps); i++ {
                if steps[i] > steps[i-1] {
                        nonIncreasing = false
                        hasIncrease = true
                }
                if steps[i] < steps[i-1] {
                        nonDecreasing = false
                }
        }
        if nonIncreasing {
                return "converging"
        }
        if nonDecreasing && hasIncrease {
                return "diverging"
        }
        return "oscillating"
}
